package com.scos.modules.maintenance.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="scos_work_order_feedback")
public class WorkOrderFeedbackEntity {
 @Id private UUID id; @Column(name="work_order_id",nullable=false,unique=true,updatable=false) private UUID workOrderId; @Column(name="resident_user_id",nullable=false,updatable=false) private UUID residentUserId; @Column(nullable=false,updatable=false) private int rating; @Column(name="feedback_comments",columnDefinition="TEXT",updatable=false) private String feedbackComments; @Column(name="resolution_confirmed",nullable=false,updatable=false) private boolean resolutionConfirmed; @Column(name="is_auto_closed",nullable=false,updatable=false) private boolean autoClosed; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt;
 @PrePersist void onCreate(){if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=Instant.now();}
 public UUID getId(){return id;} public void setId(UUID v){id=v;} public UUID getWorkOrderId(){return workOrderId;} public void setWorkOrderId(UUID v){workOrderId=v;} public UUID getResidentUserId(){return residentUserId;} public void setResidentUserId(UUID v){residentUserId=v;} public int getRating(){return rating;} public void setRating(int v){rating=v;} public String getFeedbackComments(){return feedbackComments;} public void setFeedbackComments(String v){feedbackComments=v;} public boolean isResolutionConfirmed(){return resolutionConfirmed;} public void setResolutionConfirmed(boolean v){resolutionConfirmed=v;} public boolean isAutoClosed(){return autoClosed;} public void setAutoClosed(boolean v){autoClosed=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;}
}
